function validateOps(s){const o=s.ops;if(!o){assert(s.crew.every(p=>p.tier===1)&&!s.mission?.rally,'missing ops');return;}assert(s.first&&s.build.command===2,'ops unlock');for(const k of ['workshop','academy','research'])assert(int(o[k],0,1),'ops building');assert(int(o.kits,0,1e12)&&(!o.academy&&!o.research||o.workshop),'ops stock');assert(!o.extra||s.mission,'extra mission');assert(missions(s).length<=2,'mission limit');assert(s.crew.every(p=>p.tier===1||o.academy&&o.research),'tier prerequisite');const rallies=missions(s).filter(m=>m.rally);assert(rallies.length<=1&&(!rallies.length||!s.radio.alliance.aid),'rally allocation');for(const m of rallies){const a=m.rally,v=s.radio.alliance.members[a.faction];assert(v?.pact==='allied'&&m.target.startsWith('site:')&&SITES[m.site].threat===4&&s.map[m.site].visited&&a.arrival===m.start+15,'rally route');assert(Array.isArray(a.ids)&&a.ids.length>=1&&a.ids.length<=2&&new Set(a.ids).size===a.ids.length&&a.ids.every(id=>v.guards.some(g=>g.id===id&&g.alive)),'rally guards');}if(s.job?.type==='promote')assert(o.academy&&o.research&&s.crew.find(p=>p.id===s.job.worker)?.tier===1,'promote');}
