function fieldRaid(s,m){if(!m||m.raid.done||s.time<m.raid.due)return;if(m.raid.phase==='warning'){m.raid.phase='battle';m.raid.due=s.time+30;return;}const ally=m.rally&&s.time>=m.rally.arrival?m.rally.ids.length:0;const defense=m.ids.reduce((n,id)=>n+1+bonus(s.crew.find(p=>p.id===id)),0)+ally,attack=m.raid.attack,lose=defense<attack;for(const id of m.ids){const p=s.crew.find(p=>p.id===id);if(p.tier>=2)p.kit=Math.max(0,p.kit-10);}if(lose&&ally){const a=m.rally,v=s.radio.alliance.members[a.faction];v.guards.find(g=>g.id===a.ids.shift()).alive=false;log(s,'alliance',FACTIONS[a.faction].name+'集結中一名盟兵永久陣亡。');}let dead=null,food=0,alloy=0;if(lose){dead=kill(s,s.crew.find(p=>p.id===m.ids[0]),m.raid.id);food=Math.min(4,m.food);alloy=Math.min(3,m.alloy);m.food-=food;m.alloy-=alloy;}m.raid.done=true;m.raid.result={id:m.raid.id,context:'外拓',time:s.time,defense,attack,dead,food,alloy,...(ally?{allyPower:ally}:{}),result:lose?'失利':defense===attack?'抵住（平手）':'守住'};s.lastRaid=m.raid.result;log(s,'raid',`外拓${m.raid.result.result}｜${dead?dead+' 永久陣亡':'無死亡'}｜損失${food}糧、${alloy}合金`,{settlement:m.raid.id});}
function admit(s,g){if(beds(s)-N(s)<g.names.length)return false;g.names.forEach((name,i)=>s.residents.push({id:g.id+'-'+i,name,call:'新居民',consent:true}));s.groups[g.id].phase='returned';s.groups[g.id].due=null;return true;}
function finishMission(s,m){if(!m||s.time<m.end)return;const target=m.target;let joined=0;const loot=m.alloy;const site=SITES[m.site];discover(s,m.site);if(site.faction&&s.factions[site.faction].status==='unknown'){s.factions[site.faction].status='contact';log(s,'radio',FACTIONS[site.faction].name+'已建立聯絡，電台開放有限補給交換。');}for(const id of m.ids)s.crew.find(p=>p.id===id).role='standby';joined=frontMissionFinish(s,m);const excess=unload(s,m);if(target==='gather'||target==='long'||target.startsWith('site:')){s.first=true;if(target==='gather')s.map.longwreck.known=true;}else if(m.ids.length<2){(s.companions[target]||s.groups[target]).phase='ready';log(s,'story','接應隊傷亡，未能安全帶人返回，可重新接應。');}else if(COMP[target]){s.companions[target].phase='returned';joined=1;log(s,'story',`${COMP[target].name}已實際返營。`);}else{const g=GROUPS.find(g=>g.id===target);if(admit(s,g)){joined=g.names.length;}else{s.groups[target].phase='ready';log(s,'story','接應隊返回，但救生艙居民因床位不足留在安全點，未加入。');}}s.report={id:m.id,time:s.time,target,site:m.site,crew:m.ids.filter(id=>s.crew.find(p=>p.id===id).role!=='garrison').length,food:m.food+m.cargoFood,alloy:loot,joined,raid:m.raid.result,materials:{...m.cargo},unload:excess};radioResult(s,m);if(m.rally){const a=m.rally;ops(s).report={id:m.id,site:m.site,faction:a.faction,result:m.raid.result.result,allies:a.ids.length,defense:m.raid.result.defense,attack:m.raid.attack};msg(s,allyKey(a.faction),'system','聯合集結結算：'+m.raid.result.result+'；存活盟兵已返營。沒有領土自動佔領。');}if(s.mission===m){s.mission=s.ops?.extra||null;if(s.ops)s.ops.extra=null;}else ops(s).extra=null;log(s,'return',`返營：${s.report.crew}名兵員、${m.food+m.cargoFood}口糧、${loot}合金；殘材${m.cargo.scrap}、零件${m.cargo.parts}；實際接納${joined}人。${weight(excess)?" 部分物資留在卸貨區。":""}`,{settlement:m.id});}
function finishJob(s){const j=s.job;if(!j||s.time<j.end)return;const p=s.crew.find(p=>p.id===j.worker);p.role='standby';if(j.type==='build'){s.build[j.target]++;if(j.target==='wall')s.wallHp=3;log(s,'build',(j.target==='wall'&&s.build.wall===2?'合金圍牆':BUILD[j.target].name)+'完成。');}else if(j.type==='repair'){s.wallHp=Math.min(3,s.wallHp+1);log(s,'build','路障修復完成。');}else if(j.type==='recruit'){const i=s.residents.findIndex(p=>p.id===j.target),r=s.residents.splice(i,1)[0];s.crew.push({...r,alive:true,role:'standby',tier:1});log(s,'recruit',r.name+'完成訓練，正式加入兵員。');}else if(j.type==='train'){p.role=j.target;log(s,'train',p.name+'完成'+(j.target==='ward'?'守陣':'巡衛')+'訓練。');}else if(['workshop','academy','research'].includes(j.type)){ops(s)[j.type]=1;log(s,'build',j.type+' L2 完成。');}else if(j.type==='fabricate'){putOutput(s,'kits',1);log(s,'build','T2裝備製造完成；入庫或保存在工單輸出格。');}else if(j.type==='process'){const d=RECIPES[j.target];if(j.target==='rack')s.logistics.racks++;else for(const [k,n]of Object.entries(d.out))putOutput(s,k,n);log(s,'build',d.name+'完成。');}else if(j.type==='promote'){p.tier=2;p.kit=100;log(s,'train',p.name+' 完成T2訓練及配裝。');}else if(j.type==='kitrepair'){p.kit=100;log(s,'build',p.name+' 裝備修復完成。');}else if(j.type==='recall'){log(s,'train',p.name+'完成遣返。');}finishFrontJob(s,j,p);if(j.placement){const {id,...pos}=j.placement;s.frontier.layout[id]=pos;}s.job=null;if(['build','workshop','academy','research','f_expand','f_energy','f_research','f_vehicle'].includes(j.type))syncLayout(s);}
function advance(input,seconds,{offline=false}={}){const s=clone(input);if(s.paused)return s;assert(int(seconds,0,900),'補算上限900秒');let offlineRaids=0;for(let i=0;i<seconds;i++){s.time++;const t=s.time;if(!s.baseRaid&&t>=s.nextRaid&&(!offline||offlineRaids<1)){s.baseRaid={id:nextId(s,'base'),phase:'warning',due:t+(s.build.tower&&role(s,'duty').length?60:30),defense:null};log(s,'warning','基地外圍出現敵影。請調配留守人員。');}allyTick(s);const old=s.baseRaid?.id;baseRaid(s);if(old&&!s.baseRaid)offlineRaids++;for(const m of missions(s)){frontMissionTick(s,m);collect(s,m);}if(t%300===0){for(const d of Object.values(SITES))if(d.renew){const v=s.map[d.id];v.food=Math.min(d.food,v.food+2);}}for(const m of missions(s)){fieldRaid(s,m);if((t-m.start)%90===0&&m.food&&(!m.deep||m.deep.phase==='outbound'||m.deep.phase==='return'))m.food--;finishMission(s,m);}if(s.job?.type==='process'&&s.baseRaid?.phase==='battle')s.job.end++;finishJob(s);if(s.first&&t%30===0){const r=role(s,'recycle').length,f=role(s,'supply').length,d=role(s,'duty').length;put(s,'alloy',r+(r&&d&&s.build.deep?1:0));put(s,'food',2*f+(f&&d&&s.build.dense?1:0));}for(const c of Object.values({...s.companions,...s.groups}))if(c.phase==='waiting'&&t>=c.due){c.phase='ready';c.due=null;}for(const g of GROUPS){const c=s.groups[g.id];if(c.phase==='approaching'&&t>=c.due){if(s.baseRaid)c.due=t+1;else if(admit(s,g))log(s,'return','近側救生艙三名生還者已沿安全路實際抵營。');else{c.phase='ready';c.due=null;log(s,'story','床位不足，生還者留在安全點。');}}}frontTick(s);readySignals(s);radioSync(s);allyContact(s);}assert(validate(s),'推進後狀態無效');return s;}
function reason(s,c){try{apply(clone(s),c,true);return '';}catch(e){return e.message;}}
