if(['workshop','academy','research','fabricate','promote','kitrepair'].includes(a)){assert(s.first&&s.build.command===2&&s.build.armory&&s.build.housing>=2,'需要指揮艙L2、整備艙及2座住棚');assert(!s.job,'已有施工／訓練');const o=ops(s);if(['fabricate','promote'].includes(a))assert(!weight(s.logistics.output),'先清空工單輸出格');let p=role(s,'standby')[0],secs=120;assert(p,'需要待命兵員');if(['workshop','academy','research'].includes(a)){assert(!o[a],'已完成');if(a==='academy'||a==='research')assert(o.workshop,'先建工坊L2');const future=clone(s);ops(future)[a]=1;layout(future);spend(s,0,{workshop:10,academy:12,research:8}[a]);}else if(a==='fabricate'){assert(o.workshop&&o.research,'需工坊及基礎研究');spend(s,0,3);}else if(a==='promote'){assert(o.academy&&o.research&&o.kits>0,'需整備L2、研究及1套T2裝備');p=role(s,'standby').find(p=>p.id===c.target&&p.tier===1);assert(p,'選擇T1待命兵');spend(s,4,3);o.kits--;secs=180;}else{p=role(s,'standby').find(p=>p.id===c.target&&p.tier>=2&&p.kit<100);assert(p&&o.workshop,'需待命T2兵及損耗裝備');spend(s,0,2);secs=60;}p.role='job';s.job={type:a,target:c.target||a,worker:p.id,end:s.time+secs};return;}
if(a==='build'||a==='repair'||a==='train'||a==='recall'||a==='recruit'){assert(!s.job,'已有施工／訓練');let p=role(s,'standby')[0],secs=30,target=c.target;if(a==='build'){const d=BUILD[target];assert(d,'未知建築');assert(target==='housing'||target==='command'||target==='wall'?s.build[target]<(target==='housing'?20:2):!s.build[target],'已完成');if(target==='dense')assert(s.build.supply,'先建補給棚');if(target==='command')assert(s.build.supply&&s.build.armory&&beds(s)>=13,'需要補給棚、整備艙、至少13床');assert(p,'需要1名待命施工兵');const future=clone(s);future.build[target]++;layout(future);spend(s,0,target==='wall'&&s.build.wall===1?8:d.cost);secs=d.secs;}if(a==='repair'){assert(s.build.wall&&s.wallHp<3,'路障無須修理');assert(p,'需要1名待命施工兵');spend(s,0,2);secs=60;}if(a==='train'){assert(s.build.armory,'先建整備艙');assert(['patrol','ward'].includes(target),'兵種');assert(p,'需要1名待命兵');spend(s,target==='ward'?4:3,target==='ward'?1:2);}if(a==='recall'){assert(['patrol','ward'].includes(target),'兵種');p=role(s,target)[0];assert(p,'沒有該兵種');}if(a==='recruit'){assert(s.build.armory,'先建整備艙');assert(B(s)<cap(s),'兵員容量已滿，先升指揮艙');assert(s.residents.some(p=>p.id===target&&p.consent),'沒有同意入伍的居民');assert(p,'需要1名待命教官');spend(s,3,2);secs=120;}p.role='job';s.job={type:a,target,worker:p.id,end:s.time+secs};return;}
if(a==='radio_reply'){const d=STORIES[c.id],v=s.radio.stories[c.id];assert(d&&v?.phase==='reply','尚未收到或已回覆');assert(['trace','seal'].includes(c.option),'未知回覆');v.choice=c.option;msg(s,c.id,'player',d.options.find(x=>x[0]===c.option)[1]);if(c.option==='seal'){v.phase='archived';msg(s,c.id,'system','頻道已封存。仍可自行探索地圖，不會失去已知座標。');}else{v.phase='waiting';v.due=s.time+d.delay;msg(s,c.id,'remote','收到，請等我整理訊號。');}return;}
