function validLayout(a,size=8){const occupied=new Set(['3,7']);for(const p of a){for(const [x,y]of footprint(p)){if(!int(x,0,size-1)||!int(y,0,size-1)||occupied.has(x+','+y))return false;occupied.add(x+','+y);}if(p.kind==='wall'&&p.x!==0&&p.x!==size-1&&p.y!==0&&p.y!==size-1&&p.y!==7)return false;}occupied.delete('3,7');const seen=new Set(['3,7']),q=[[3,7]];while(q.length){const [x,y]=q.shift();for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const X=x+dx,Y=y+dy,k=X+','+Y;if(int(X,0,size-1)&&int(Y,0,size-1)&&!occupied.has(k)&&!seen.has(k)){seen.add(k);q.push([X,Y]);}}}return a.every(p=>footprint(p).some(([x,y])=>[[1,0],[-1,0],[0,1],[0,-1]].some(([dx,dy])=>seen.has((x+dx)+','+(y+dy)))));}
